def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return out

    # Extend a diagonal pair of matching colored cells away from the rest
    # of its object.
    from collections import Counter
    positions = Counter((r, c, v) for r, c, v in pts)
    for r, c, v in pts:
        for dr in (-1, 1):
            for dc in (-1, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == v:
                    # Continue outward from this end of the diagonal pair.
                    pr, pc = r - dr, c - dc
                    if not (0 <= pr < h and 0 <= pc < w and grid[pr][pc] == v):
                        rr, cc = r - dr, c - dc
                        while 0 <= rr < h and 0 <= cc < w:
                            if out[rr][cc] == bg:
                                out[rr][cc] = v
                            rr -= dr
                            cc -= dc
    return out
